namespace ghidra.app.plugin.core.datamgr.actions;






using com.google.gson;

using docking.widgets.tree;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.model.data.ISF;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

public class DataTypeWriterTask : Task {

	private DataTypeManager programDataTypeMgr;
	private List<DataType> dataTypeList;
	private File file;
	private GTree gTree;

	public DataTypeWriterTask(GTree gTree, DataTypeManager programDataTypeMgr, List<DataType> dataTypeList, File file) : base("Export Data Types", true, false, true)
    {
		this.gTree = gTree;
		this.programDataTypeMgr = programDataTypeMgr;
		this.dataTypeList = dataTypeList;
		this.file = file;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {
		try {
			//monitor.setMessage("Export to " + file.getName() + "...");
			FileWriter baseWriter = file == null ? null : new FileWriter(file);
			IsfDataTypeWriter dataTypeWriter = new IsfDataTypeWriter(programDataTypeMgr, dataTypeList, baseWriter);

			try {
				JsonObject @object = dataTypeWriter.getRootObject(monitor);
				if (file != null) {
					dataTypeWriter.write(@object);
				}
			} finally {
				dataTypeWriter.close();
			}
		} catch (CancelledException e) {
			// user cancelled; ignore
		} catch (IOException e) {
			Msg.showError(getClass(), gTree, "Export Data Types Failed", "Error exporting Data Types: " + e);
			return;
		}
	}
}
